import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, step, color, vec3 } from 'three/tsl';
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'bento-metrics-grid';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    surface: '#14141a',
    accent: '#ff2a38',
    paper: '#e8ecf2',
    gradA: '#101017',
    gradB: '#1a1a22'
  };

  const disposables = [];
  const timelines = [];

  function gradientMaterial() {
    const uvNode = uv();
    const diag = uvNode.x.add(uvNode.y).div(2.0);
    const base = mix(color(colors.gradA), color(colors.gradB), diag);
    // hard-stop sheen band around 40%
    const band = step(0.38, diag).sub(step(0.53, diag));
    const sheen = base.add(vec3(0.06, 0.06, 0.06).mul(band));
    const mat = new MeshStandardNodeMaterial();
    mat.colorNode = sheen;
    mat.roughness = 0.5;
    mat.metalness = 0.45;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.3;
    disposables.push(mat);
    return mat;
  }

  function makeCell(w, h, x, y) {
    const geo = new THREE.BoxGeometry(w, h, 0.06);
    disposables.push(geo);
    const mat = gradientMaterial();
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x, y, 0.03);
    mesh.scale.set(1, 1, 1);

    // chamfer edge highlight (simple frame)
    const edgeGeo = new THREE.EdgesGeometry(geo);
    disposables.push(edgeGeo);
    const edgeMat = new MeshBasicNodeMaterial({ color: 0x2a2a33, transparent: true, opacity: 0.5 });
    disposables.push(edgeMat);
    const edges = new THREE.LineSegments(edgeGeo, edgeMat);
    mesh.add(edges);

    // tick bar
    const tickGeo = new THREE.BoxGeometry(0.4, 0.05, 0.02);
    disposables.push(tickGeo);
    const tickMat = new MeshStandardNodeMaterial({ color: colors.accent });
    tickMat.emissive = new THREE.Color(colors.accent);
    tickMat.emissiveIntensity = 1.3;
    disposables.push(tickMat);
    const tick = new THREE.Mesh(tickGeo, tickMat);
    tick.position.set(-w / 2 + 0.5 + 0.2, h / 2 - 0.5 - 0.025, 0.05);
    mesh.add(tick);

    return mesh;
  }

  function makeText(text, typography, color, x, y, z) {
    let textObj;
    try {
      textObj = ctx.fontAtlas.createText({
        text,
        font: typography.family,
        fontSize: typography.fontSize,
        fontWeight: typography.fontWeight,
        letterSpacing: typography.letterSpacing,
        lineHeight: typography.lineHeight,
        color
      });
    } catch (e) {
      textObj = new THREE.Object3D();
    }
    if (textObj) {
      textObj.position.set(x, y, z);
    }
    return textObj;
  }

  const typography = {
    value: { family: 'Lora', fontSize: 68, fontWeight: 600, letterSpacing: -0.005, lineHeight: 1.05 },
    valueLarge: { family: 'Lora', fontSize: 124, fontWeight: 600, letterSpacing: -0.01, lineHeight: 1 },
    label: { family: 'JetBrains Mono', fontSize: 18, fontWeight: 400, letterSpacing: 0.08, lineHeight: 1.4 },
    caption: { family: 'JetBrains Mono', fontSize: 18, fontWeight: 700, letterSpacing: 0.12, lineHeight: 1.4 }
  };

  // Header caption
  const header = makeText('ATELIER METRICS / Q2 2026', typography.caption, colors.paper, -2.75, 2.0, 0.1);
  group.add(header);

  // Dominant cell (left column, both rows): 3.25 x 3.5
  const dominant = makeCell(3.25, 3.5, -1.125, 0);
  group.add(dominant);
  const domValue = makeText('0.002 mm', typography.valueLarge, colors.paper, -1.125 - 1.0, 0.3, 0.07);
  dominant.add(domValue);
  const domLabel = makeText('Case tolerance, CNC pass', typography.label, colors.paper, -1.125 - 1.0, -0.2, 0.07);
  dominant.add(domLabel);

  // Secondary top cell: 2.0 x 1.625
  const secTop = makeCell(2.0, 1.625, 1.75, 0.9375);
  group.add(secTop);
  const secTopValue = makeText('38 h', typography.value, colors.paper, 1.75 - 0.7, 1.1, 0.07);
  secTop.add(secTopValue);
  const secTopLabel = makeText('Power reserve, NA-01', typography.label, colors.paper, 1.75 - 0.7, 0.8, 0.07);
  secTop.add(secTopLabel);

  // Secondary bottom cell
  const secBottom = makeCell(2.0, 1.625, 1.75, -0.9375);
  group.add(secBottom);
  const secBottomValue = makeText('214', typography.value, colors.paper, 1.75 - 0.7, -0.75, 0.07);
  secBottom.add(secBottomValue);
  const secBottomLabel = makeText('Components per calibre', typography.label, colors.paper, 1.75 - 0.7, -1.05, 0.07);
  secBottom.add(secBottomLabel);

  // Entrance animation: stagger-cards / fade-up, dominant first
  const cells = [dominant, secTop, secBottom];
  cells.forEach((cell) => {
    cell.userData._origY = cell.position.y;
    cell.position.y += 0.2;
    cell.scale.set(0.999, 0.999, 0.999);
  });

  cells.forEach((cell, i) => {
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(cell.position, {
      y: cell.userData._origY,
      duration: 0.5,
      ease: 'power2.out'
    });
    tl.fromTo(
      cell.scale,
      { x: 0.999, y: 0.999, z: 0.999 },
      { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power2.out' },
      0
    );
    timelines.push(tl);
  });

  // Hover handlers (press-down / weighted-settle) applied to whole group cells
  function attachHover(cell) {
    cell.userData.onPointerDown = () => {
      gsap.to(cell.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    };
    cell.userData.onPointerUp = () => {
      gsap.to(cell.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.05, onComplete: () => {
        const settleTl = gsap.to(cell.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
        timelines.push(settleTl);
      }});
    };
  }
  cells.forEach(attachHover);

  group.userData.handlers = {
    onPointerDown: (event) => {
      const target = event && event.target;
      if (target && target.userData && target.userData.onPointerDown) {
        target.userData.onPointerDown();
      }
    },
    onPointerUp: (event) => {
      const target = event && event.target;
      if (target && target.userData && target.userData.onPointerUp) {
        target.userData.onPointerUp();
      }
    }
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') {
        res.dispose();
      }
    });
    disposables.length = 0;
  };

  return group;
}
